        StreamArtistIdentityState.Mutation memory m =
            StreamArtistIdentityHistoryMutation.importEncoded(
                _replay, _ownerContext(), artistWindowAuthority, msg.data
            );
        _commit(c, m.action, m.state, m.replay, m.record);
    }

