        record = StreamArtistHashes.payoutRecordForAuthority(
            o.environment,
            p,
            proof.signer,
            identity.identities[p.artistId].authorityClass,
            a.nonce,
            a.time
        );
        m = StreamArtistIdentityState.authorize(
            identity,
            replay,
            o,
            c,
            p.artistId,
