    function _unavailabilityPins() private view {
        for (uint256 i; i < 16;) {
            if (_targets[i].codehash != _runtimeHashes[i]) revert T.ComponentChanged(_targets[i]);
            // The constructor-fixed sixteen pins bound this loop.
            unchecked {
                ++i;
