            if (f.tokenCount != 1 || f.sourceRecordHash != 0 || f.scopeManifestHash != 0) {
                revert InvalidScopedProviderMetadata();
            }
            return (false, bytes32(0));
        }
        if (f.sourceRecordHash == 0 || f.scopeManifestHash == 0) {
