    function _assemblyPerformSanctionAndFinality() internal {
        require(
            assemblyCompleteBundle.bundleCoverageHash != 0,
            "complete original bundle before sanction"
        );
        StreamFinalityScope memory scope = _assemblyScope();
        bytes memory raw = assemblyProvider.inputManifestBytes(scope);
        require(raw.length != 0 && raw.length <= 8192, "actual independent complete input manifest");
        bytes32[] memory chunks = _assemblyUpload(raw);
        require(
            chunks.length == 1 && chunks[0] == keccak256(raw)
                && assemblyFinality.stageFinalityManifest(raw) == chunks[0],
            "same complete original two-store manifest"
        );
        StreamFinalityManifestRef memory manifest = StreamFinalityManifestRef(
            "https://fixtures.example.invalid/native-assembly/finality-input-manifest",
            keccak256(
                bytes("https://fixtures.example.invalid/native-assembly/finality-input-manifest")
            ),
            chunks[0],
            keccak256("6529STREAM_FINALITY_INPUT_MANIFEST_V1"),
            keccak256("6529STREAM_FINALITY_INPUT_MANIFEST_ABI_V1")
        );
        (uint256 count, bytes32 independentHash) =
            assemblyDiscovery.nonSanctionDiscoveryFacts(scope);
        require(count == 9, "actual independent nine-family discovery");
        AssemblySanctionRequest.Request memory request;
        request.nonSanctionComponents = new StreamFinalityComponentExpectation[](count);
        for (uint256 i; i < count; ++i) {
            request.nonSanctionComponents[i] = assemblyDiscovery.nonSanctionComponentAt(scope, i);
        }
        require(
            assemblyFinality.computeComponentsHash(request.nonSanctionComponents)
                == independentHash,
            "exact discovery ordering"
        );
        request.manifest = manifest;
        request.terms.collectionId = 1;
        request.statement =
            "I approve these exact original onchain artworks, reference renders and preservation records for this fixture's finality ceremony.";
        request.signingToolName = "Native actual Safe fixture";
        request.signingToolVersion = "1";
        AssemblySanctionRequest.Prepared memory prepared =
            assemblyArtists.prepareArtistSanction(request);
        request.terms.sanctionSubjectHash = StreamArtistSanctionHashes.subject(prepared.subject);
        request.terms.statementHash = keccak256(prepared.ceremony);
        AssemblySanctionRequest.Prepared memory repeated =
            assemblyArtists.prepareArtistSanction(request);
        require(
            keccak256(abi.encode(prepared)) == keccak256(abi.encode(repeated)),
            "acyclic exact original ceremony"
        );
        T.Authorization memory authorization = _assemblyAuthorization(false);
        bytes32 digest = assemblyArtists.sanctionDigest(request.terms, authorization);
        authorization.signature = _assemblyArtistProof(digest, authorization.nonce);
        assemblySanctionRecord = assemblyArtists.recordArtistSanction(request, authorization);
        AssemblySanction.Record memory saved =
            assemblyArtists.sanctionRecord(assemblySanctionRecord);
        require(
            saved.recordHash == assemblySanctionRecord && saved.artistId == assemblyArtistId
                && saved.signer == address(assemblyArtist) && saved.authorityClass == 1
                && saved.nonce == authorization.nonce && saved.digest == digest
                && keccak256(abi.encode(saved.terms)) == keccak256(abi.encode(request.terms)),
            "actual nonce-backed original Safe sanction"
        );
        raw = assemblyArtists.sanctionArchiveBytes(assemblySanctionRecord);
        (bytes32 artifact, bytes32 completion) = _ocCover(
            raw,
            keccak256("6529STREAM_ARTIST_SANCTION_ARCHIVE_V1"),
            keccak256("6529STREAM_ARTIST_SANCTION_ARCHIVE_ABI_V1")
        );
        StreamFinalitySanctionArchiveProof memory proof =
            StreamFinalitySanctionArchiveProof(assemblySanctionRecord, artifact, completion);
        require(
            assemblyDiscovery.finalityComponentCountForScope(scope) == 10,
            "actual complete ten-family discovery"
        );
        StreamFinalityComponentExpectation[] memory components =
            new StreamFinalityComponentExpectation[](10);
        for (uint256 i; i < components.length; ++i) {
            components[i] = assemblyDiscovery.finalityComponentAtForScope(scope, i);
        }
        bytes32 componentHash = assemblyFinality.computeComponentsHash(components);
        require(
            componentHash == assemblyDiscovery.finalityDiscoveryHashForScope(scope),
            "complete actual discovery commitment"
        );
        bytes32 coreHash = assemblyFinality.computeCollectionCoreFactsHash(1);
        assemblyFinalityRecord =
            assemblyFinality.computeFinalityRecordHash(scope, coreHash, componentHash, manifest);
        StreamFinalityExecutionContext memory execution =
            assemblyFinality.finalityExecutionContextWithArchive(
                scope, components, assemblyFinalityRecord, manifest, proof
            );
        bytes32 action = _assemblyGovernanceCall(
            2,
            address(assemblyFinality),
            abi.encodeCall(
                assemblyFinality.finalizeCollectionArtworkWithArchive,
                (1, components, assemblyFinalityRecord, manifest, proof)
            ),
            execution.scopeHash,
            execution.oldValueHash,
            execution.newValueHash
        );
        StreamCollectionFinalityRecord memory finalized =
            assemblyFinality.collectionFinalityRecord(1);
        StreamFinalityExecutionWitness memory witness =
            assemblyFinality.finalityExecutionWitness(assemblyFinalityRecord);
        StreamFinalitySanctionArchiveWitness memory archived =
            assemblyFinality.finalitySanctionArchiveWitness(assemblyFinalityRecord);
        require(
            finalized.finalized && finalized.finalityRecordHash == assemblyFinalityRecord
                && finalized.manifestContentHash == manifest.contentHash
                && finalized.componentsHash == componentHash && witness.actionId == action
                && witness.proposer == address(assemblyRoot) && witness.roleRevision != 0
                && archived.evidenceHash != 0
                && keccak256(abi.encode(archived.proof)) == keccak256(abi.encode(proof)),
            "actual canonical class2 finality with original sanction archive"
        );
    }

    // Each factory call is a separate broadcast transaction; only the original slot creates the host.

    function _graphCreation(StreamCurrentGraphCreation.Kind kind)
        internal
        view
        override
        returns (bytes memory)
    {
        return StreamCurrentGraphCreation.creation(kind);
    }

    function _authorityCreation(StreamCurrentAuthorityGraphCreation.Kind kind)
        internal
        pure
        override
        returns (bytes memory)
    {
        return StreamCurrentAuthorityGraphCreation.code(kind);
    }

    function _afterCurrentAuthorityCoordinatorDeployment() internal virtual override {
        _installAssemblyArtistPointer();
    }

    function _assemblyArtistProof(bytes32 digest, uint256 nonce) internal returns (bytes memory) {
        _authorityAuthorization(digest, nonce);
        return _assemblyArtistProof(digest);
    }

    /// @dev Derived recipes retain genuine Artist signing preimages; this hook changes no authority.
    function _authorityAuthorization(bytes32 digest, uint256 nonce) internal virtual { }
    /// @dev STATIC activation must happen before the first release ratification and first mint.
    function _beforeAssemblyArtistOnboarding() internal virtual { }
    function _afterAssemblyTokenFinalized(uint256) internal virtual { }
    function _afterAssemblyOnboard() internal virtual { }

    function _authorityEconomicsConsent(T.EconomicsConsent memory input, bytes32 record)
        internal
        virtual { }
    function _authorityRatification(T.Ratification memory input, bytes32 record)
        internal
        virtual { }
    function _authorityPolicyConsent(T.PolicyConsent memory input, bytes32 record)
        internal
        virtual { }
    function _authorityAttestation(T.Attestation memory input, uint256 nonce, bytes32 record)
        internal
        virtual { }
    function _authorityContentConsent(AssemblyContent.Consent memory input, bytes32 record)
        internal
        virtual { }
    function _authorityContentFreeze(AssemblyContent.Freeze memory input, bytes32 record)
        internal
        virtual { }

    /// @dev A separate actual transition; finalization itself does not silently confirm Artist state.
    function _assemblyConfirmSanctionFinalized() internal {
        require(
            assemblySanctionRecord != 0 && assemblyFinalityRecord != 0,
            "actual saved sanction and finality"
        );
        FixtureAuthority.Anchors memory anchorsBefore = assemblyAuthorityResolver.anchors();
        FixtureAuthority.Selection memory selected = assemblyAuthorityResolver.currentSelection();
        FixtureAuthority.Route memory routeBefore =
            assemblyAuthorityResolver.currentFinalityRoute(1);
        require(
            routeBefore.registry == selected.origin.environment.registry
                && routeBefore.finalityRegistry == address(assemblyFinality)
                && routeBefore.finalityRegistry == anchorsBefore.finalityRegistry,
            "actual current sanction route"
        );
        address originalArtist = address(assemblyFinality.sanctionReads());
        require(originalArtist == anchorsBefore.targets[3], "original Finality Artist anchor");
        StreamArtistOnboardingRegistry current =
            StreamArtistOnboardingRegistry(payable(selected.origin.environment.registry));
        AssemblySanction.Record memory sanctionBefore =
            current.sanctionRecord(assemblySanctionRecord);
        require(
            sanctionBefore.recordHash == assemblySanctionRecord
                && sanctionBefore.artistId == assemblyArtistId,
            "current saved sanction"
        );
        StreamCollectionFinalityRecord memory finalized =
            assemblyFinality.collectionFinalityRecord(1);
        require(
            finalized.finalized && finalized.finalityRecordHash == assemblyFinalityRecord,
            "actual finalized record"
        );
        T.Snapshot[7] memory before_;
        for (uint256 i; i < 7; ++i) {
            before_[i] =
                IStreamArtistOwner(selected.origin.environment.owners[i]).ownerStateSnapshotV2();
        }
        IStreamArtistSanctionConfirmation(address(current)).confirmSanctionFinalized(1);
        (uint8 state, uint64 generation) =
            IStreamArtistAttributionOwner(selected.origin.environment.owners[4]).attributionState(1);
        T.Binding memory binding_ =
            IStreamArtistBindingOwner(selected.origin.environment.owners[0]).binding(1);
        require(
            state == 3 && generation == binding_.generation,
            "actual current sanction-confirmed Attribution"
        );
        for (uint256 i; i < 7; ++i) {
            T.Snapshot memory after_ =
                IStreamArtistOwner(selected.origin.environment.owners[i]).ownerStateSnapshotV2();
            if (i == 4 || i == 6) {
                require(
                    after_.revision == before_[i].revision + 1
                        && after_.recordChainTip == before_[i].recordChainTip,
                    "one confirmation commit without primary record"
                );
            } else {
                require(
                    keccak256(abi.encode(after_)) == keccak256(abi.encode(before_[i])),
                    "unrelated current owner unchanged"
                );
            }
        }
        require(
            keccak256(abi.encode(sanctionBefore))
                    == keccak256(abi.encode(current.sanctionRecord(assemblySanctionRecord)))
                && keccak256(abi.encode(finalized))
                    == keccak256(abi.encode(assemblyFinality.collectionFinalityRecord(1))),
            "saved sanction and finality unchanged"
        );
        require(
            address(assemblyFinality.sanctionReads()) == originalArtist
                && keccak256(abi.encode(anchorsBefore))
                    == keccak256(abi.encode(assemblyAuthorityResolver.anchors()))
                && keccak256(abi.encode(routeBefore))
                    == keccak256(abi.encode(assemblyAuthorityResolver.currentFinalityRoute(1))),
            "original anchors and selected route unchanged"
        );
    }

    function _assemblyPublishManifest(
        StreamSystemManifest.ModuleAddresses memory modules,
        bytes32 reason
    ) internal returns (GovernanceCall memory call_, bytes memory data) {
        return _assemblyPublication(modules, reason);
    }

    function _assemblyReceiptWitness(bytes32 id, uint8 ownerIndex, uint16 operation, bytes32 record)
        internal
        view
        returns (FixtureOrigin.ReceiptWitness memory)
    {
        return
            _assemblyReceiptWitnessFor(
                address(assemblyInventory), id, ownerIndex, operation, record
            );
    }

    function _assemblyReceiptWitnessFor(
        address inventory,
        bytes32 id,
        uint8 ownerIndex,
        uint16 operation,
        bytes32 record
    ) internal view returns (FixtureOrigin.ReceiptWitness memory) {
        require(ownerIndex < 7 && record != 0, "exact receipt query");
        FixtureAuthorityInventory.Capture memory captured =
            IStreamCurrentAuthorityInventory(inventory).authoritySelection(id);
        address owner = captured.selection.origin.environment.owners[ownerIndex];
        uint256 count = IStreamArtistNativeReceipts(owner).artistNativeReceiptCount();
        for (uint256 i; i < count; ++i) {
            FixtureHistory.Receipt memory receipt =
                IStreamArtistNativeReceipts(owner).artistNativeReceiptAt(i);
            if (
                receipt.operation == operation && receipt.recordHash == record
                    && receipt.artistId == assemblyArtistId && receipt.collectionId == 1
            ) {
                return FixtureOrigin.ReceiptWitness(FixtureOrigin.Lane.NATIVE, i);
            }
        }
        (FixtureHydration.OwnerProvenance memory prefix, bytes32 commitment, uint64 revision) =
            IStreamArtistRecoveredHydrationOwner(owner).recoveredHydrationImportedPrefix();
        require(commitment != 0 && revision != 0, "actual imported prefix");
        for (uint256 i; i < prefix.journal.length; ++i) {
            FixtureHydration.JournalEntry memory saved = prefix.journal[i];
            if (
                saved.receipt.operation != operation || saved.receipt.recordHash != record
                    || saved.receipt.artistId != assemblyArtistId || saved.receipt.collectionId != 1
            ) continue;
            (FixtureHydration.JournalEntry memory bounded, bytes32 imported, uint64 atRevision) =
                IStreamArtistImportedReceiptRead(owner).recoveredHydrationImportedReceiptAt(i);
            require(
                saved.position.point.ownerIndex == ownerIndex && imported == commitment
                    && atRevision == revision
                    && keccak256(abi.encode(bounded)) == keccak256(abi.encode(saved)),
                "exact bounded imported receipt"
            );
            return FixtureOrigin.ReceiptWitness(FixtureOrigin.Lane.IMPORTED, i);
        }
        revert("actual original receipt membership missing");
    }
}

